window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a19913e1c85e687e"]={"versions": [{"id": "FIG-a19913e1c85e687e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&P Safety</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Chassis Domain Software-Komponenten (<code>SW-C</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamik & Verzögerung:</strong></li>\n<li><code>CrsCtrlAndAcc</code>: Cruise Control & Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung).</li>\n<li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).</li>\n<li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).</li>\n<li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).</li>\n<li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).</li>\n<li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).</li>\n<li><strong>Vertikaldynamik & Monitoring:</strong></li>\n<li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).</li>\n<li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).</li>\n<li><strong>Querdynamik & Allradmanagement:</strong></li>\n<li><code>DtTqDibtn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring).</li>\n<li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).</li>\n<li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).</li>\n<li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).</li>\n</ul>\n<p class=\"fig-p\">#### Interne Kopplungen (Chassis-interne Assoziationen)</p>\n<ul class=\"fig-list\">\n<li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCtrlAndAcc</code> $\\rightarrow$ <code>Vlc</code> $\\rightarrow$ <code>Ssm</code> / <code>Rsc</code> $\\rightarrow$ <code>Esc</code> sowie <code>Ssm</code> $\\rightarrow$ <code>Epb</code> $\\rightarrow$ <code>Esc</code>.</li>\n<li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.</li>\n</ul>\n<p class=\"fig-p\">#### Externe Domänen & Schnittstellenkanäle (1–26)</p>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\">\n<li><strong>Globale Broadcast-Schnittstellen (Body $\\rightarrow$ alle Chassis-SW-Cs):</strong></li>\n<li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).</li>\n<li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).</li>\n<li><strong>Numerierte Abhängigkeiten im Detail:</strong></li>\n<li><code>1</code> (Powertrain $\\rightarrow$ <code>CrsCtrlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.</li>\n<li><code>2</code> (<code>CrsCtrlAndAcc</code> $\\rightarrow$ P&P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung.</li>\n<li><code>3</code> (<code>CrsCtrlAndAcc</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>4</code> (<code>Vlc</code> $\\leftrightarrow$ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.</li>\n<li><code>5</code> (Body $\\rightarrow$ <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.</li>\n<li><code>6</code> (<code>Ssm</code> $\\leftrightarrow$ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.</li>\n<li><code>7</code> (<code>Ssm</code> $\\rightarrow$ HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.</li>\n<li><code>8</code> (Powertrain $\\rightarrow$ <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.</li>\n<li><code>9</code> (<code>Esc</code> $\\rightarrow$ Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.</li>\n<li><code>10</code> (<code>Esc</code> $\\leftrightarrow$ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.</li>\n<li><code>11</code> (<code>Esc</code> $\\leftrightarrow$ P&P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.</li>\n<li><code>12</code> (<code>Esc</code> $\\leftrightarrow$ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.</li>\n<li><code>13</code> (Body $\\rightarrow$ <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.</li>\n<li><code>14</code> (Powertrain $\\rightarrow$ <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).</li>\n<li><code>15</code> (<code>Susp</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.</li>\n<li><code>16</code> (<code>DtTqDibtn</code> $\\rightarrow$ Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).</li>\n<li><code>17</code> (<code>DtTqDibtn</code> $\\rightarrow$ HMI): P-Port; Allrad-/Verteilungsstatus.</li>\n<li><code>18</code> (Body $\\rightarrow$ <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.</li>\n<li><code>19</code> (Powertrain $\\rightarrow$ <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).</li>\n<li><code>20</code> (<code>TirePMon</code> $\\leftrightarrow$ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>21</code> (<code>Steer</code> $\\rightarrow$ Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).</li>\n<li><code>22</code> (<code>Steer</code> $\\leftrightarrow$ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.</li>\n<li><code>23</code> (<code>SteerVehStabyCtrl</code> $\\leftrightarrow$ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.</li>\n<li><code>24</code> (<code>SteerDrvrAsscSys</code> $\\leftrightarrow$ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.</li>\n<li><code>25</code> (<code>Steer</code> $\\rightarrow$ Body): P-Port; Lenkradwinkel für dynamisches Kurvenlicht.</li>\n<li><code>26</code> (<code>Epb</code> $\\leftrightarrow$ HMI): Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).</li>\n<li><strong>Arbitrierungs- und Override-Kaskade:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.</li>\n<li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).</li>\n<li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Port-Konfiguration:</strong></li>\n<li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>).</li>\n<li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.</li>\n<li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong></li>\n<li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.</li>\n<li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong></li>\n<li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von $\\le 10\\,\\text{ms}$.</li>\n<li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).</li>\n<li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong></li>\n<li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.</li>\n</ul>"}, {"id": "FIG-b17eda362c999ef7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&P Safety</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Chassis Domain Software-Komponenten (<code>SW-C</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamik & Verzögerung:</strong></li>\n<li><code>CrsCrtlAndAcc</code>: Cruise Control & Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung; im Diagramm mit Schreibweise <code>CrsCrtl</code>).</li>\n<li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).</li>\n<li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).</li>\n<li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).</li>\n<li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).</li>\n<li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).</li>\n<li><strong>Vertikaldynamik & Monitoring:</strong></li>\n<li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).</li>\n<li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).</li>\n<li><strong>Querdynamik & Allradmanagement:</strong></li>\n<li><code>DtTqDistbn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring; Schreibweise korrigiert von <code>DtTqDibtn</code>).</li>\n<li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).</li>\n<li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).</li>\n<li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).</li>\n<li><strong>Parkassistenz:</strong></li>\n<li><code>PrkgAid</code>: Parking Aid (Parksensorik und Einparkassistenz; neu ergänzt).</li>\n</ul>\n<p class=\"fig-p\">#### Interne Kopplungen (Chassis-interne Assoziationen)</p>\n<ul class=\"fig-list\">\n<li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCrtlAndAcc</code> $\\rightarrow$ <code>Vlc</code> $\\rightarrow$ <code>Ssm</code> / <code>Rsc</code> $\\rightarrow$ <code>Esc</code> sowie <code>Ssm</code> $\\rightarrow$ <code>Epb</code> $\\rightarrow$ <code>Esc</code>.</li>\n<li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.</li>\n</ul>\n<p class=\"fig-p\">#### Externe Domänen & Schnittstellenkanäle (1–27)</p>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\">\n<li><strong>Globale Broadcast-Schnittstellen (Body $\\rightarrow$ alle Chassis-SW-Cs):</strong></li>\n<li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).</li>\n<li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).</li>\n<li><strong>Numerierte Abhängigkeiten im Detail:</strong></li>\n<li><code>1</code> (Powertrain $\\rightarrow$ <code>CrsCrtlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.</li>\n<li><code>2</code> (<code>CrsCrtlAndAcc</code> $\\rightarrow$ P&P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>3</code> (<code>CrsCrtlAndAcc</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>4</code> (<code>Vlc</code> $\\leftrightarrow$ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.</li>\n<li><code>5</code> (Body $\\rightarrow$ <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.</li>\n<li><code>6</code> (<code>Ssm</code> $\\leftrightarrow$ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.</li>\n<li><code>7</code> (<code>Ssm</code> $\\rightarrow$ HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.</li>\n<li><code>8</code> (Powertrain $\\rightarrow$ <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.</li>\n<li><code>9</code> (<code>Esc</code> $\\rightarrow$ Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.</li>\n<li><code>10</code> (<code>Esc</code> $\\leftrightarrow$ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.</li>\n<li><code>11</code> (<code>Esc</code> $\\leftrightarrow$ P&P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.</li>\n<li><code>12</code> (<code>Esc</code> $\\leftrightarrow$ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.</li>\n<li><code>13</code> (Body $\\rightarrow$ <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.</li>\n<li><code>14</code> (Powertrain $\\rightarrow$ <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).</li>\n<li><code>15</code> (<code>Susp</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.</li>\n<li><code>16</code> (<code>DtTqDistbn</code> $\\rightarrow$ Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).</li>\n<li><code>17</code> (<code>DtTqDistbn</code> $\\rightarrow$ HMI): P-Port; Allrad-/Verteilungsstatus.</li>\n<li><code>18</code> (Body $\\rightarrow$ <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.</li>\n<li><code>19</code> (Powertrain $\\rightarrow$ <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).</li>\n<li><code>20</code> (<code>TirePMon</code> $\\leftrightarrow$ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>21</code> (<code>Steer</code> $\\rightarrow$ Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).</li>\n<li><code>22</code> (<code>Steer</code> $\\leftrightarrow$ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.</li>\n<li><code>23</code> (<code>SteerVehStabyCtrl</code> $\\leftrightarrow$ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.</li>\n<li><code>24</code> (<code>SteerDrvrAsscSys</code> $\\leftrightarrow$ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.</li>\n<li><code>25</code> (Mehrfachbelegung im Diagramm):</li>\n<li><code>Steer</code> $\\rightarrow$ Body: P-Port; Lenkradwinkel für dynamisches Kurvenlicht.</li>\n<li>Body $\\rightarrow$ <code>PrkgAid</code>: R-Port; Ultraschallsensor- und Stoßfängerdaten, Rückwärtsgangstatus.</li>\n<li><code>26</code> (Mehrfachbelegung im Diagramm):</li>\n<li><code>Epb</code> $\\leftrightarrow$ HMI: Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li>Powertrain $\\rightarrow$ <code>PrkgAid</code>: R-Port; Raddrehzahl-, Geschwindigkeits- und Getriebeinformationen.</li>\n<li><code>27</code> (<code>PrkgAid</code> $\\leftrightarrow$ HMI): Bidirektional; Parkhilfetaster (Aktivierung/Deaktivierung) vs. akustische und optische Distanzanzeige.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).</li>\n<li><strong>Arbitrierungs- und Override-Kaskade:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.</li>\n<li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).</li>\n<li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Port-Konfiguration:</strong></li>\n<li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>).</li>\n<li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.</li>\n<li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong></li>\n<li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.</li>\n<li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong></li>\n<li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von $\\le 10\\,\\text{ms}$.</li>\n<li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).</li>\n<li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong></li>\n<li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.</li>\n</ul>"}, {"id": "FIG-86fbe7eaf98ad092", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&P Safety</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Chassis Domain Software-Komponenten (<code>SW-C</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamik & Verzögerung:</strong></li>\n<li><code>CrsCrtlAndAcc</code>: Cruise Control & Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung; im Diagramm mit Schreibweise <code>CrsCrtl</code>).</li>\n<li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).</li>\n<li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).</li>\n<li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).</li>\n<li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).</li>\n<li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).</li>\n<li><strong>Vertikaldynamik & Monitoring:</strong></li>\n<li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).</li>\n<li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).</li>\n<li><strong>Querdynamik & Allradmanagement:</strong></li>\n<li><code>DtTqDistbn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring; Schreibweise korrigiert von <code>DtTqDibtn</code>).</li>\n<li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).</li>\n<li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).</li>\n<li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).</li>\n<li><strong>Parkassistenz:</strong></li>\n<li><code>PrkgAid</code>: Parking Aid (Parksensorik und Einparkassistenz; neu ergänzt).</li>\n</ul>\n<p class=\"fig-p\">#### Interne Kopplungen (Chassis-interne Assoziationen)</p>\n<ul class=\"fig-list\">\n<li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCrtlAndAcc</code> $\\rightarrow$ <code>Vlc</code> $\\rightarrow$ <code>Ssm</code> / <code>Rsc</code> $\\rightarrow$ <code>Esc</code> sowie <code>Ssm</code> $\\rightarrow$ <code>Epb</code> $\\rightarrow$ <code>Esc</code>.</li>\n<li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.</li>\n</ul>\n<p class=\"fig-p\">#### Externe Domänen & Schnittstellenkanäle (1–27)</p>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\">\n<li><strong>Globale Broadcast-Schnittstellen (Body $\\rightarrow$ alle Chassis-SW-Cs):</strong></li>\n<li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).</li>\n<li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).</li>\n<li><strong>Numerierte Abhängigkeiten im Detail:</strong></li>\n<li><code>1</code> (Powertrain $\\rightarrow$ <code>CrsCrtlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.</li>\n<li><code>2</code> (<code>CrsCrtlAndAcc</code> $\\rightarrow$ P&P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>3</code> (<code>CrsCrtlAndAcc</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>4</code> (<code>Vlc</code> $\\leftrightarrow$ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.</li>\n<li><code>5</code> (Body $\\rightarrow$ <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.</li>\n<li><code>6</code> (<code>Ssm</code> $\\leftrightarrow$ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.</li>\n<li><code>7</code> (<code>Ssm</code> $\\rightarrow$ HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.</li>\n<li><code>8</code> (Powertrain $\\rightarrow$ <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.</li>\n<li><code>9</code> (<code>Esc</code> $\\rightarrow$ Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.</li>\n<li><code>10</code> (<code>Esc</code> $\\leftrightarrow$ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.</li>\n<li><code>11</code> (<code>Esc</code> $\\leftrightarrow$ P&P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.</li>\n<li><code>12</code> (<code>Esc</code> $\\leftrightarrow$ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.</li>\n<li><code>13</code> (Body $\\rightarrow$ <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.</li>\n<li><code>14</code> (Powertrain $\\rightarrow$ <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).</li>\n<li><code>15</code> (<code>Susp</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.</li>\n<li><code>16</code> (<code>DtTqDistbn</code> $\\rightarrow$ Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).</li>\n<li><code>17</code> (<code>DtTqDistbn</code> $\\rightarrow$ HMI): P-Port; Allrad-/Verteilungsstatus.</li>\n<li><code>18</code> (Body $\\rightarrow$ <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.</li>\n<li><code>19</code> (Powertrain $\\rightarrow$ <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).</li>\n<li><code>20</code> (<code>TirePMon</code> $\\leftrightarrow$ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>21</code> (<code>Steer</code> $\\rightarrow$ Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).</li>\n<li><code>22</code> (<code>Steer</code> $\\leftrightarrow$ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.</li>\n<li><code>23</code> (<code>SteerVehStabyCtrl</code> $\\leftrightarrow$ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.</li>\n<li><code>24</code> (<code>SteerDrvrAsscSys</code> $\\leftrightarrow$ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.</li>\n<li><code>25</code> (Mehrfachbelegung im Diagramm):</li>\n<li><code>Steer</code> $\\rightarrow$ Body: P-Port; Lenkradwinkel für dynamisches Kurvenlicht.</li>\n<li>Body $\\rightarrow$ <code>PrkgAid</code>: R-Port; Ultraschallsensor- und Stoßfängerdaten, Rückwärtsgangstatus.</li>\n<li><code>26</code> (Mehrfachbelegung im Diagramm):</li>\n<li><code>Epb</code> $\\leftrightarrow$ HMI: Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li>Powertrain $\\rightarrow$ <code>PrkgAid</code>: R-Port; Raddrehzahl-, Geschwindigkeits- und Getriebeinformationen.</li>\n<li><code>27</code> (<code>PrkgAid</code> $\\leftrightarrow$ HMI): Bidirektional; Parkhilfetaster (Aktivierung/Deaktivierung) vs. akustische und optische Distanzanzeige.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).</li>\n<li><strong>Arbitrierungs- und Override-Kaskade:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.</li>\n<li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).</li>\n<li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Port-Konfiguration:</strong></li>\n<li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>).</li>\n<li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.</li>\n<li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong></li>\n<li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.</li>\n<li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong></li>\n<li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von $\\le 10\\,\\text{ms}$.</li>\n<li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).</li>\n<li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong></li>\n<li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.</li>\n</ul>"}, {"id": "FIG-45135d2fddb2d9d3", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&P Safety</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Chassis Domain Software-Komponenten (<code>SW-C</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>Längsdynamik & Verzögerung:</strong></li>\n<li><code>CrsCrtlAndAcc</code>: Cruise Control & Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung; im Diagramm mit Schreibweise <code>CrsCrtl</code>).</li>\n<li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).</li>\n<li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).</li>\n<li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).</li>\n<li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).</li>\n<li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).</li>\n<li><strong>Vertikaldynamik & Monitoring:</strong></li>\n<li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).</li>\n<li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).</li>\n<li><strong>Querdynamik & Allradmanagement:</strong></li>\n<li><code>DtTqDistbn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring; Schreibweise korrigiert von <code>DtTqDibtn</code>).</li>\n<li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).</li>\n<li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).</li>\n<li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).</li>\n<li><strong>Parkassistenz:</strong></li>\n<li><code>PrkgAid</code>: Parking Aid (Parksensorik und Einparkassistenz; neu ergänzt).</li>\n</ul>\n<p class=\"fig-p\">#### Interne Kopplungen (Chassis-interne Assoziationen)</p>\n<ul class=\"fig-list\">\n<li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCrtlAndAcc</code> $\\rightarrow$ <code>Vlc</code> $\\rightarrow$ <code>Ssm</code> / <code>Rsc</code> $\\rightarrow$ <code>Esc</code> sowie <code>Ssm</code> $\\rightarrow$ <code>Epb</code> $\\rightarrow$ <code>Esc</code>.</li>\n<li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.</li>\n</ul>\n<p class=\"fig-p\">#### Externe Domänen & Schnittstellenkanäle (1–27)</p>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\">\n<li><strong>Globale Broadcast-Schnittstellen (Body $\\rightarrow$ alle Chassis-SW-Cs):</strong></li>\n<li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).</li>\n<li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).</li>\n<li><strong>Numerierte Abhängigkeiten im Detail:</strong></li>\n<li><code>1</code> (Powertrain $\\rightarrow$ <code>CrsCrtlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.</li>\n<li><code>2</code> (<code>CrsCrtlAndAcc</code> $\\rightarrow$ P&P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>3</code> (<code>CrsCrtlAndAcc</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>4</code> (<code>Vlc</code> $\\leftrightarrow$ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.</li>\n<li><code>5</code> (Body $\\rightarrow$ <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.</li>\n<li><code>6</code> (<code>Ssm</code> $\\leftrightarrow$ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.</li>\n<li><code>7</code> (<code>Ssm</code> $\\rightarrow$ HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.</li>\n<li><code>8</code> (Powertrain $\\rightarrow$ <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.</li>\n<li><code>9</code> (<code>Esc</code> $\\rightarrow$ Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.</li>\n<li><code>10</code> (<code>Esc</code> $\\leftrightarrow$ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.</li>\n<li><code>11</code> (<code>Esc</code> $\\leftrightarrow$ P&P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.</li>\n<li><code>12</code> (<code>Esc</code> $\\leftrightarrow$ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.</li>\n<li><code>13</code> (Body $\\rightarrow$ <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.</li>\n<li><code>14</code> (Powertrain $\\rightarrow$ <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).</li>\n<li><code>15</code> (<code>Susp</code> $\\leftrightarrow$ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.</li>\n<li><code>16</code> (<code>DtTqDistbn</code> $\\rightarrow$ Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).</li>\n<li><code>17</code> (<code>DtTqDistbn</code> $\\rightarrow$ HMI): P-Port; Allrad-/Verteilungsstatus.</li>\n<li><code>18</code> (Body $\\rightarrow$ <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.</li>\n<li><code>19</code> (Powertrain $\\rightarrow$ <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).</li>\n<li><code>20</code> (<code>TirePMon</code> $\\leftrightarrow$ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li><code>21</code> (<code>Steer</code> $\\rightarrow$ Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).</li>\n<li><code>22</code> (<code>Steer</code> $\\leftrightarrow$ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.</li>\n<li><code>23</code> (<code>SteerVehStabyCtrl</code> $\\leftrightarrow$ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.</li>\n<li><code>24</code> (<code>SteerDrvrAsscSys</code> $\\leftrightarrow$ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.</li>\n<li><code>25</code> (Mehrfachbelegung im Diagramm):</li>\n<li><code>Steer</code> $\\rightarrow$ Body: P-Port; Lenkradwinkel für dynamisches Kurvenlicht.</li>\n<li>Body $\\rightarrow$ <code>PrkgAid</code>: R-Port; Ultraschallsensor- und Stoßfängerdaten, Rückwärtsgangstatus.</li>\n<li><code>26</code> (Mehrfachbelegung im Diagramm):</li>\n<li><code>Epb</code> $\\leftrightarrow$ HMI: Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).</li>\n<li>Powertrain $\\rightarrow$ <code>PrkgAid</code>: R-Port; Raddrehzahl-, Geschwindigkeits- und Getriebeinformationen.</li>\n<li><code>27</code> (<code>PrkgAid</code> $\\leftrightarrow$ HMI): Bidirektional; Parkhilfetaster (Aktivierung/Deaktivierung) vs. akustische und optische Distanzanzeige.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).</li>\n<li><strong>Arbitrierungs- und Override-Kaskade:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.</li>\n<li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).</li>\n<li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Port-Konfiguration:</strong></li>\n<li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>).</li>\n<li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.</li>\n<li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong></li>\n<li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.</li>\n<li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong></li>\n<li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von $\\le 10\\,\\text{ms}$.</li>\n<li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).</li>\n<li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong></li>\n<li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.</li>\n</ul>"}], "trans": [{"from": "FIG-a19913e1c85e687e", "to": "FIG-b17eda362c999ef7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PrkgAid</code>: Neue Software-Komponente für Parkassistenz im Fahrwerk-Domänenüberblick ergänzt.</li>\n<li>Schnittstelle <code>25</code> (Body $\\rightarrow$ <code>PrkgAid</code>): Neuer R-Port für Parksensordaten; erzeugt Doppelbelegung mit bestehendem P-Port <code>Steer</code> $\\rightarrow$ Body.</li>\n<li>Schnittstelle <code>26</code> (Powertrain $\\rightarrow$ <code>PrkgAid</code>): Neuer R-Port für Fahrzustandssignale; erzeugt Doppelbelegung mit bestehender Schnittstelle <code>Epb</code> $\\leftrightarrow$ HMI.</li>\n<li>Schnittstelle <code>27</code> (<code>PrkgAid</code> $\\leftrightarrow$ HMI): Neue bidirektionale Schnittstelle zur Parkassistenzbedienung und optisch-akustischen Warnung.</li>\n<li><code>DtTqDibtn</code> $\\rightarrow$ <code>DtTqDistbn</code>: Komponentenbezeichnung redaktionell korrigiert (Einfügen von 's').</li>\n<li><code>CrsCtrlAndAcc</code> $\\rightarrow$ <code>CrsCrtlAndAcc</code>: Typografische Änderung in der Komponentenbeschriftung.</li>\n<li>Legende: Typenbezeichnung von <code>Chassis domain SW-</code> zu <code>Chassis domain SW-C</code> korrigiert.</li>\n</ul>"}, {"from": "FIG-b17eda362c999ef7", "to": "FIG-86fbe7eaf98ad092", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-86fbe7eaf98ad092", "to": "FIG-45135d2fddb2d9d3", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
